import { OPTIONS, integer, number, strictInteger, strictNumber } from './';

function mask(maskers, value) {
  return maskers.reduce((newValue, masker) => {
    switch (masker) {
      case OPTIONS.integer:
        return integer(value);
      case OPTIONS.number:
        return number(value);
      case OPTIONS.strictInteger:
        return strictInteger(value);
      case OPTIONS.strictNumber:
        return strictNumber(value);
      default:
        return newValue;
    }
  }, value);
}

export default mask;
